const uint lane = thread_index_in_simdgroup;
const uint row = threadgroup_position_in_grid.x * 4 + simdgroup_index_in_threadgroup;
if (row >= rows) return;
const uint base = row * H;

float ss = 0.0f;
if (H % 4 == 0) {
    const uint V = H / 4;
    half4 hv[32];
    #pragma unroll
    for (uint j = 0; j < 32; j++) {
        uint i = lane + j * 32;
        if (i < V) {
            half4 v = ld4(x, base + i * 4) + ld4(r, base + i * 4);
            hv[j] = v;
            st4(h, base + i * 4, v);
            float4 f = float4(v);
            ss += dot(f, f);
        }
    }
    for (uint i = lane + 1024; i < V; i += 32) {
        half4 v = ld4(x, base + i * 4) + ld4(r, base + i * 4);
        st4(h, base + i * 4, v);
        float4 f = float4(v);
        ss += dot(f, f);
    }
    const float inv = rsqrt(simd_sum(ss) / float(H) + 1e-5f);
    #pragma unroll
    for (uint j = 0; j < 32; j++) {
        uint i = lane + j * 32;
        if (i < V) st4(y, base + i * 4, half4(float4(hv[j]) * (float4(ld4(w, i * 4)) * inv)));
    }
    for (uint i = lane + 1024; i < V; i += 32) {
        float4 f = float4(ld4(h, base + i * 4));
        st4(y, base + i * 4, half4(f * (float4(ld4(w, i * 4)) * inv)));
    }
} else {
    for (uint i = lane; i < H; i += 32) {
        half v = half(float(x[base + i]) + float(r[base + i]));
        h[base + i] = v;
        float f = float(v);
        ss += f * f;
    }
    const float inv = rsqrt(simd_sum(ss) / float(H) + 1e-5f);
    for (uint i = lane; i < H; i += 32) {
        y[base + i] = half(float(h[base + i]) * inv * float(w[i]));
    }
}

